from kit import *
CAT = "differentiation"
def G(expr, var="x"): return ("deriv", diff(X(expr), var))
def dc(fam, expr, lines, expect, var="x", **kw):
    add(CAT, fam, dprob(expr, var), lines, expect, goal=G(expr, var), var=var, restate=X(expr), **kw)

def build():
    # ---------------------------------------------------------------- valid, conventional
    s = St("plain", dstyle="prime")
    dc("poly-prime", "4*x^5 - 3*x^2 + 7", [defn(s, "f", "4*x^5 - 3*x^2 + 7"), eq(s, ("D", "f"), "20*x^4 - 6*x", final=True)], "verified", tags=["valid"])
    s = St("implicit", var="t", f="g", dstyle="prime")
    dc("poly-negpower", "2*t^3 + 5*t - 1/t", [defn(s, "g", "2*t^3 + 5*t - 1/t"), eq(s, ("D", "g"), "6*t^2 + 5 + 1/t^2", final=True)], "verified", var="t", tags=["valid", "symbol-t"])
    s = St("implicit", dstyle="prime")
    dc("chain-power", "(3*x + 1)^5", [defn(s, "f", "(3*x + 1)^5"), eq(s, ("D", "f"), "5*(3*x + 1)^4*3", "15*(3*x + 1)^4", final=True)], "verified", tags=["valid"])
