    s = St("implicit", dstyle="leib")
    dc("chain-substitution-lines", "ln(x^2 + 1)", [defn(s, "u", "x^2 + 1", "eq"), defn(s, "y", "ln(u)", "eq"), eq(s, ("D", "y", "u"), "1/u"), eq(s, ("D", "u"), "2*x"), eq(s, ("D", "y"), "1/u*2*x", "2*x/(x^2 + 1)", final=True)], "verified", tags=["valid", "substitution-lines"])
    s = St("unicode", dstyle="dd")
    dc("product", "x^2*e^x", [eq(s, ("D", "x^2*e^x"), "2*x*e^x + x^2*e^x", "(2*x + x^2)*e^x", final=True)], "verified", tags=["valid"])
    s = St("plain", dstyle="prime")
    dc("product-with-parts", "x*ln(x)", [defn(s, "f", "x*ln(x)"), defn(s, "u", "x", "eq"), defn(s, "v", "ln(x)", "eq"), eq(s, ("D", "f"), "1*ln(x) + x*(1/x)", "ln(x) + 1", final=True)], "verified", tags=["valid"])
    s = St("implicit", dstyle="prime")
    dc("quotient", "(x^2 + 1)/(x - 3)", [defn(s, "f", "(x^2 + 1)/(x - 3)"), eq(s, ("D", "f"), "(2*x*(x - 3) - (x^2 + 1)*1)/(x - 3)^2", "(x^2 - 6*x - 1)/(x - 3)^2", final=True)], "verified", tags=["valid"])
    s = St("plain", dstyle="dd")
    dc("quotient-trig", "sin(x)/x", [eq(s, ("D", "sin(x)/x"), "(x*cos(x) - sin(x))/x^2", final=True)], "verified", tags=["valid"])
    s = St("unicode", dstyle="leib")
    dc("chain-sqrt", "sqrt(1 - x^2)", [defn(s, "y", "sqrt(1 - x^2)", "eq"), eq(s, ("D", "y"), "1/(2*sqrt(1 - x^2))*(-2*x)", "-x/sqrt(1 - x^2)", final=True)], "verified", tags=["valid"])
    s = St("implicit", dstyle="prime")
    dc("chain-tan", "tan(5*x)", [defn(s, "f", "tan(5*x)"), eq(s, ("D", "f"), "5/cos(5*x)^2", final=True)], "verified", tags=["valid"])
    s = St("plain", dstyle="leib")
    dc("chain-compose-exp-sin", "e^(sin(x))", [defn(s, "y", "e^(sin(x))", "eq"), eq(s, ("D", "y"), "e^(sin(x))*cos(x)", final=True)], "verified", tags=["valid"])
    s = St("unicode", dstyle="prime")
    dc("chain-log-trig", "ln(cos(x))", [defn(s, "f", "ln(cos(x))"), eq(s, ("D", "f"), "1/cos(x)*(-sin(x))", "-sin(x)/cos(x)", "-tan(x)", final=True)], "verified", tags=["valid"])
    s = St("latex", dstyle="dd")
    dc("chain-power-poly", "(x^2 + x)^7", [eq(s, ("D", "(x^2 + x)^7"), "7*(x^2 + x)^6*(2*x + 1)", final=True)], "verified", tags=["valid", "latex"])
