    s = St("unicode", dstyle="prime")
    dc("quotient-const-num", "1/(x^2 + 4)", [defn(s, "f", "1/(x^2 + 4)"), eq(s, ("D", "f"), "(0*(x^2 + 4) - 1*(2*x))/(x^2 + 4)^2", "-2*x/(x^2 + 4)^2", final=True)], "verified", tags=["valid"])
    s = St("implicit", dstyle="dd")
    dc("product-sqrt", "x*sqrt(x + 1)", [eq(s, ("D", "x*sqrt(x + 1)"), "sqrt(x + 1) + x/(2*sqrt(x + 1))", final=True)], "verified", tags=["valid"])
    s = St("plain", dstyle="prime")
