    s = St("unicode", dstyle="dd")
    dc("constant-multiple-pulled-out", "6*sin(2*x)", [eq(s, ("D", "6*sin(2*x)"), "6*(d_PLACEHOLDER)") if False else eq(s, ("D", "6*sin(2*x)"), "6*(cos(2*x)*2)", "12*cos(2*x)", final=True)], "verified", alt=True, tags=["valid", "alternative"])
    s = St("plain", dstyle="prime")
    dc("alt-negative-exponent", "1/(x^2 + 4)", [defn(s, "f", "1/(x^2 + 4)"), eq(s, "1/(x^2 + 4)", "(x^2 + 4)^(-1)"), eq(s, ("D", "f"), "(-1)*(x^2 + 4)^(-2)*(2*x)", "-2*x/(x^2 + 4)^2", final=True)], "verified", alt=True, tags=["valid", "alternative"])
    s = St("implicit", dstyle="dd")
    dc("sum-split", "x^2 + sin(x)", [eq(s, ("D", "x^2 + sin(x)"), "2*x + cos(x)", final=True)], "verified", alt=True, tags=["valid", "alternative"])
    # ---------------------------------------------------------------- invalid
    s = St("plain", dstyle="prime")
    dc("err-chain-missing-inner", "(3*x + 1)^5", [defn(s, "f", "(3*x + 1)^5"), eq(s, ("D", "f"), "5*(3*x + 1)^4", final=True)], "invalid", tags=["wrong-chain"])
    s = St("implicit", dstyle="leib")
    dc("err-chain-trig-inner", "sin(x^2)", [defn(s, "y", "sin(x^2)", "eq"), eq(s, ("D", "y"), "cos(x^2)", final=True)], "invalid", tags=["wrong-chain"])
    s = St("unicode", dstyle="dd")
    dc("err-product-uv", "x^2*e^x", [eq(s, ("D", "x^2*e^x"), "2*x*e^x", final=True)], "invalid", tags=["wrong-product"])
    s = St("plain", dstyle="prime")
    dc("err-quotient-sign", "(x^2 + 1)/(x - 3)", [defn(s, "f", "(x^2 + 1)/(x - 3)"), eq(s, ("D", "f"), "((x^2 + 1)*1 - 2*x*(x - 3))/(x - 3)^2", final=True)], "invalid", tags=["wrong-quotient"])
    s = St("implicit", dstyle="prime")
    dc("err-power-rule", "3*x^4", [defn(s, "f", "3*x^4"), eq(s, ("D", "f"), "12*x^4", final=True)], "invalid", tags=["wrong-power"])
    s = St("plain", dstyle="leib")
    dc("err-trig-sign", "cos(2*x)", [defn(s, "y", "cos(2*x)", "eq"), eq(s, ("D", "y"), "2*sin(2*x)", final=True)], "invalid", tags=["sign"])
    s = St("implicit", dstyle="prime")
    dc("err-log-chain", "ln(3*x)", [defn(s, "f", "ln(3*x)"), eq(s, ("D", "f"), "1/(3*x)", final=True)], "invalid", tags=["wrong-chain"])
    s = St("unicode", dstyle="prime")
    dc("err-exp-chain", "e^(2*x)", [defn(s, "f", "e^(2*x)"), eq(s, ("D", "f"), "e^(2*x)", final=True)], "invalid", tags=["wrong-chain"])
    s = St("plain", dstyle="leib")
    dc("final-ok-after-invalid-middle", "(2*x + 3)^4", [defn(s, "y", "(2*x + 3)^4", "eq"), eq(s, ("D", "y"), "4*(2*x + 3)^3"), eq(s, ("D", "y"), "8*(2*x + 3)^3", final=True)], "invalid", first_ok=[1], tags=["correct-final-after-error"])
    s = St("implicit", dstyle="dd")
    dc("final-ok-after-invalid-product", "x*sin(x)", [eq(s, ("D", "x*sin(x)"), "cos(x) + sin(x)"), eq(s, ("D", "x*sin(x)"), "sin(x) + x*cos(x)", final=True)], "invalid", first_ok=[0], tags=["correct-final-after-error"])
    s = St("plain", dstyle="leib")
    dc("final-ok-after-invalid-substitution", "ln(x^2 + 1)", [defn(s, "u", "x^2 + 1", "eq"), defn(s, "y", "ln(u)", "eq"), eq(s, ("D", "y", "u"), "1/u"), eq(s, ("D", "u"), "x"), eq(s, ("D", "y"), "2*x/(x^2 + 1)", final=True)], "invalid", first_ok=[3], tags=["correct-final-after-error"])
    s = St("unicode", dstyle="prime")
    dc("final-ok-after-quotient-slip", "(x + 1)/(x - 1)", [defn(s, "f", "(x + 1)/(x - 1)"), eq(s, ("D", "f"), "((x - 1) - (x + 1)*(-1))/(x - 1)^2"), eq(s, ("D", "f"), "-2/(x - 1)^2", final=True)], "invalid", first_ok=[1], tags=["correct-final-after-error"])
    s = St("implicit", dstyle="prime")
    dc("err-expansion-alt", "(x + 2)*(x - 3)", [defn(s, "f", "(x + 2)*(x - 3)"), eq(s, "(x + 2)*(x - 3)", "x^2 - 6"), eq(s, ("D", "f"), "2*x - 1", final=True)], "invalid", first_ok=[1], tags=["wrong-expansion"])
    s = St("plain", dstyle="prime")
    dc("err-restated-function", "x^3 + 2*x", [defn(s, "f", "x^3 - 2*x"), eq(s, ("D", "f"), "3*x^2 - 2", final=True)], "invalid", first_ok=[0], tags=["restatement-mismatch"])
    s = St("latex", dstyle="dd")
    dc("err-constant-multiple", "5*e^(3*x)", [eq(s, ("D", "5*e^(3*x)"), "5*e^(3*x)", final=True)], "invalid", tags=["wrong-chain", "latex"])
